import {
  createContext,
  useContext,
  useState,
  type ReactNode,
} from "react";
import { authStorage } from "../../services/auth.storage";

interface LoginFormState {
  email: string;
  password: string;
  setEmail: (email: string) => void;
  setPassword: (password: string) => void;
  submit: (onSuccess: () => void) => void;
}

const LoginFormContext = createContext<LoginFormState | null>(null);

export function LoginFormProvider({ children }: { children: ReactNode }) {
  const [email, setEmail] = useState("demo@example.com");
  const [password, setPassword] = useState("password123");

  function submit(onSuccess: () => void) {
    authStorage.login();
    onSuccess();
  }

  return (
    <LoginFormContext.Provider
      value={{ email, password, setEmail, setPassword, submit }}
    >
      {children}
    </LoginFormContext.Provider>
  );
}

export function useLoginForm() {
  const ctx = useContext(LoginFormContext);
  if (!ctx) throw new Error("useLoginForm must be used within LoginFormProvider");
  return ctx;
}

