import { type FormEvent } from "react";
import { LoginFormProvider, useLoginForm } from "./LoginForm.context";

interface LoginFormProps {
  onSuccess: () => void;
}

function LoginFormInner({ onSuccess }: LoginFormProps) {
  const { email, password, setEmail, setPassword, submit } = useLoginForm();

  function handleSubmit(e: FormEvent) {
    e.preventDefault();
    submit(onSuccess);
  }

  return (
    <form onSubmit={handleSubmit}>
      <input
        type="email"
        required
        placeholder="name@example.com"
        value={email}
        onChange={(e) => setEmail(e.target.value)}
      />
      <input
        type="password"
        required
        value={password}
        onChange={(e) => setPassword(e.target.value)}
      />
      <button type="submit">Sign In</button>
    </form>
  );
}

export function LoginForm({ onSuccess }: LoginFormProps) {
  return (
    <LoginFormProvider>
      <LoginFormInner onSuccess={onSuccess} />
    </LoginFormProvider>
  );
}

