import { safeLocalStorage } from "@/lib/storage/safe-local-storage";
import type { Workspace, AvatarColor } from "../model/workspace.types";

const WORKSPACES_KEY = "workspaces";

const AVATAR_COLORS: AvatarColor[] = [
  "blue",
  "green",
  "purple",
  "orange",
  "red",
  "teal",
];

const DEFAULT_WORKSPACES: Workspace[] = [
  {
    id: "acme-corp",
    name: "Acme Corp",
    initials: "AC",
    role: "Owner",
    avatarColor: "blue",
  },
  {
    id: "personal-dashboard",
    name: "Personal Dashboard",
    initials: "PD",
    role: "Owner",
    avatarColor: "green",
  },
  {
    id: "startup-project",
    name: "Startup Project",
    initials: "SP",
    role: "Owner",
    avatarColor: "purple",
  },
];

export const workspaceStorage = {
  getAll(): Workspace[] {
    const raw = safeLocalStorage.getItem(WORKSPACES_KEY);
    if (!raw) {
      this.saveAll(DEFAULT_WORKSPACES);
      return DEFAULT_WORKSPACES;
    }
    try {
      return JSON.parse(raw) as Workspace[];
    } catch {
      return DEFAULT_WORKSPACES;
    }
  },

  saveAll(workspaces: Workspace[]): void {
    safeLocalStorage.setItem(WORKSPACES_KEY, JSON.stringify(workspaces));
  },

  add(workspace: Workspace): void {
    const current = this.getAll();
    this.saveAll([...current, workspace]);
  },

  remove(id: string): void {
    const current = this.getAll();
    this.saveAll(current.filter((w) => w.id !== id));
  },

  getById(id: string): Workspace | undefined {
    return this.getAll().find((w) => w.id === id);
  },

  nextAvatarColor(workspaces: Workspace[]): AvatarColor {
    return AVATAR_COLORS[workspaces.length % AVATAR_COLORS.length];
  },
};

