import type { Workspace, CreateWorkspaceInput } from "../model/workspace.types";
import type { AvatarColor } from "../model/workspace.types";

function parseRepoName(url: string): string {
  const trimmed = url.trim();
  const sshMatch = trimmed.match(/git@[^:]+:([^/]+)\/(.+?)(?:\.git)?$/);
  if (sshMatch) return sshMatch[2];
  try {
    const parsed = new URL(trimmed);
    const parts = parsed.pathname.replace(/^\//, "").replace(/\.git$/, "").split("/");
    return parts[parts.length - 1] ?? trimmed;
  } catch {
    return trimmed;
  }
}

function deriveInitials(name: string): string {
  return name
    .split(/[-_ /]/)
    .filter(Boolean)
    .slice(0, 2)
    .map((part) => part[0]?.toUpperCase() ?? "")
    .join("");
}

export const workspaceImportService = {
  validate(
    url: string,
    privateRepository: boolean,
    token: string,
    existingWorkspaces: Workspace[]
  ): string | null {
    const trimmed = url.trim();
    if (!trimmed) return "Please enter a repository URL";

    if (
      !trimmed.startsWith("https://") &&
      !trimmed.startsWith("http://") &&
      !trimmed.startsWith("git@")
    ) {
      return "URL must start with https://, http://, or git@";
    }

    const duplicate = existingWorkspaces.find(
      (w) => w.repositoryUrl === trimmed
    );
    if (duplicate) return `"${duplicate.name}" already imported`;

    if (privateRepository && !token.trim()) {
      return "GitHub personal access token is required for private repositories";
    }

    return null;
  },

  createWorkspace(
    input: CreateWorkspaceInput,
    avatarColor: AvatarColor
  ): Workspace {
    const name = parseRepoName(input.repositoryUrl);
    return {
      id: `${name.toLowerCase().replace(/[^a-z0-9]+/g, "-")}-${Date.now()}`,
      name,
      initials: deriveInitials(name),
      role: "Owner",
      avatarColor,
      repositoryUrl: input.repositoryUrl,
      privateRepository: input.privateRepository,
      tokenConfigured: input.tokenConfigured,
    };
  },
};

