import { useState, useCallback } from "react";
import { workspaceStorage } from "../services/workspace.storage";
import type { Workspace } from "../model/workspace.types";

export function useWorkspaces() {
  const [workspaces, setWorkspaces] = useState<Workspace[]>(() =>
    workspaceStorage.getAll()
  );

  const addWorkspace = useCallback((workspace: Workspace) => {
    workspaceStorage.add(workspace);
    setWorkspaces(workspaceStorage.getAll());
  }, []);

  const removeWorkspace = useCallback((id: string) => {
    workspaceStorage.remove(id);
    setWorkspaces(workspaceStorage.getAll());
  }, []);

  const getWorkspace = useCallback(
    (id: string) => workspaces.find((w) => w.id === id),
    [workspaces]
  );

  return { workspaces, addWorkspace, removeWorkspace, getWorkspace };
}

