import {
  createContext,
  useState,
  useCallback,
  type ReactNode,
} from "react";
import type { WorkspaceImportContext as IWorkspaceImportContext } from "../../model/workspace-import.types";
import { workspaceImportService } from "../../services/workspace-import.service";
import { workspaceStorage } from "../../services/workspace.storage";

export const WorkspaceImportContext =
  createContext<IWorkspaceImportContext | null>(null);

interface WorkspaceImportProviderProps {
  children: ReactNode;
  onImported?: (workspaceId: string) => void;
}

export function WorkspaceImportProvider({
  children,
  onImported,
}: WorkspaceImportProviderProps) {
  const [url, setUrlState] = useState("");
  const [privateRepository, setPrivateRepository] = useState(false);
  const [token, setToken] = useState("");
  const [error, setError] = useState<string | null>(null);
  const [importing, setImporting] = useState(false);

  const setUrl = useCallback((value: string) => {
    setUrlState(value);
    setError(null);
  }, []);

  const setPrivateRepositoryToggle = useCallback((enabled: boolean) => {
    setPrivateRepository(enabled);
    if (!enabled) setToken("");
  }, []);

  const clearError = useCallback(() => setError(null), []);

  const reset = useCallback(() => {
    setUrlState("");
    setPrivateRepository(false);
    setToken("");
    setError(null);
    setImporting(false);
  }, []);

  const submit = useCallback(
    (onImportedCallback: (workspaceId: string) => void) => {
      const existing = workspaceStorage.getAll();
      const validationError = workspaceImportService.validate(
        url,
        privateRepository,
        token,
        existing
      );
      if (validationError) {
        setError(validationError);
        return;
      }

      setImporting(true);
      setTimeout(() => {
        const avatarColor = workspaceStorage.nextAvatarColor(existing);
        const workspace = workspaceImportService.createWorkspace(
          {
            repositoryUrl: url.trim(),
            privateRepository,
            tokenConfigured: privateRepository && token.trim().length > 0,
          },
          avatarColor
        );
        workspaceStorage.add(workspace);
        setUrlState("");
        setToken("");
        setImporting(false);
        onImportedCallback(workspace.id);
        onImported?.(workspace.id);
      }, 400);
    },
    [url, privateRepository, token, onImported]
  );

  return (
    <WorkspaceImportContext.Provider
      value={{
        url,
        privateRepository,
        token,
        error,
        importing,
        setUrl,
        setPrivateRepository: setPrivateRepositoryToggle,
        setToken,
        clearError,
        submit,
        reset,
      }}
    >
      {children}
    </WorkspaceImportContext.Provider>
  );
}

