import { type ReactNode } from "react";
import {
  WorkspaceImportProvider,
  WorkspaceImportContext,
} from "./WorkspaceImport.context";
import { useContext } from "react";

function useImport() {
  const ctx = useContext(WorkspaceImportContext);
  if (!ctx)
    throw new Error("WorkspaceImport parts must be used inside WorkspaceImport.Root");
  return ctx;
}

interface RootProps {
  children: ReactNode;
  onImported?: (workspaceId: string) => void;
}

function Root({ children, onImported }: RootProps) {
  return (
    <WorkspaceImportProvider onImported={onImported}>
      {children}
    </WorkspaceImportProvider>
  );
}

function UrlField() {
  const { url, setUrl, importing } = useImport();
  return (
    <input
      type="url"
      placeholder="https://github.com/owner/repo"
      value={url}
      disabled={importing}
      onChange={(e) => setUrl(e.target.value)}
    />
  );
}

function PrivateRepositorySwitch() {
  const { privateRepository, setPrivateRepository } = useImport();
  return (
    <label>
      <input
        type="checkbox"
        checked={privateRepository}
        onChange={(e) => setPrivateRepository(e.target.checked)}
      />
      <span>Private repository</span>
    </label>
  );
}

function TokenField() {
  const { privateRepository, token, setToken, importing } = useImport();
  if (!privateRepository) return null;
  return (
    <div>
      <label htmlFor="github-token">GITHUB PERSONAL ACCESS TOKEN</label>
      <input
        id="github-token"
        type="password"
        placeholder="ghp_xxxxxxxxxxxxxxxxxxxx"
        value={token}
        disabled={importing}
        onChange={(e) => setToken(e.target.value)}
      />
    </div>
  );
}

function ErrorMessage() {
  const { error } = useImport();
  if (!error) return null;
  return <p role="alert">{error}</p>;
}

function SubmitButton({ onImported }: { onImported?: (id: string) => void }) {
  const { url, importing, submit } = useImport();
  return (
    <button
      type="button"
      disabled={importing || !url.trim()}
      onClick={() => submit(onImported ?? (() => {}))}
    >
      {importing ? "Importing..." : "Import"}
    </button>
  );
}

function WorkspaceImportRoot({ children, onImported }: RootProps) {
  return <Root onImported={onImported}>{children}</Root>;
}

export const WorkspaceImport = WorkspaceImportRoot as typeof WorkspaceImportRoot & {
  UrlField: typeof UrlField;
  PrivateRepositorySwitch: typeof PrivateRepositorySwitch;
  TokenField: typeof TokenField;
  ErrorMessage: typeof ErrorMessage;
  SubmitButton: typeof SubmitButton;
};

WorkspaceImport.UrlField = UrlField;
WorkspaceImport.PrivateRepositorySwitch = PrivateRepositorySwitch;
WorkspaceImport.TokenField = TokenField;
WorkspaceImport.ErrorMessage = ErrorMessage;
WorkspaceImport.SubmitButton = SubmitButton;

