import { workspaceStorage } from "../../services/workspace.storage";
import type { Workspace } from "../../model/workspace.types";

interface WorkspaceSwitcherState {
  isOpen: boolean;
  currentWorkspace: Workspace | undefined;
  otherWorkspaces: Workspace[];
  open: () => void;
  close: () => void;
  toggle: () => void;
}

