  WorkspaceSwitcherProvider,
  useWorkspaceSwitcher,
} from "./WorkspaceSwitcher.context";

interface RootProps {
  children: ReactNode;
  workspaceId: string;
}

function Root({ children, workspaceId }: RootProps) {
  return (
    <WorkspaceSwitcherProvider workspaceId={workspaceId}>
      {children}
    </WorkspaceSwitcherProvider>
  );
}

function Trigger() {
  const { currentWorkspace, toggle } = useWorkspaceSwitcher();
  return (
    <button
      type="button"
      onClick={toggle}
      title={currentWorkspace?.name ?? "Workspace"}
    >
      {currentWorkspace?.initials ?? "?"}
    </button>
  );
}

function Dropdown({ children }: { children: ReactNode }) {
  const { isOpen } = useWorkspaceSwitcher();
  if (!isOpen) return null;
  return <div>{children}</div>;
}

function WorkspaceSwitcherRoot({ children, workspaceId }: RootProps) {
  return <Root workspaceId={workspaceId}>{children}</Root>;
}

export const WorkspaceSwitcher =
  WorkspaceSwitcherRoot as typeof WorkspaceSwitcherRoot & {
    Trigger: typeof Trigger;
    Dropdown: typeof Dropdown;
  };

WorkspaceSwitcher.Trigger = Trigger;
WorkspaceSwitcher.Dropdown = Dropdown;

