  useState,
  useCallback,
  type ReactNode,
} from "react";

interface AddWorkspaceModalState {
  isOpen: boolean;
  open: () => void;
  close: () => void;
}

const AddWorkspaceModalContext =
  createContext<AddWorkspaceModalState | null>(null);

export function AddWorkspaceModalProvider({ children }: { children: ReactNode }) {
  const [isOpen, setIsOpen] = useState(false);
  const open = useCallback(() => setIsOpen(true), []);
  const close = useCallback(() => setIsOpen(false), []);
  return (
    <AddWorkspaceModalContext.Provider value={{ isOpen, open, close }}>
      {children}
    </AddWorkspaceModalContext.Provider>
  );
}

export function useAddWorkspaceModal() {
  const ctx = useContext(AddWorkspaceModalContext);
  if (!ctx)
    throw new Error(
      "useAddWorkspaceModal must be used within AddWorkspaceModalProvider"
    );
  return ctx;
}

