import { useState, useCallback } from "react";
import type { TaskStatus, BoardFilters } from "../model/board.types";

export function useBoardFilters() {
  const [query, setQuery] = useState("");
  const [statuses, setStatuses] = useState<Set<TaskStatus>>(new Set());

  const toggleStatus = useCallback((status: TaskStatus) => {
    setStatuses((prev) => {
      const next = new Set(prev);
      if (next.has(status)) {
        next.delete(status);
      } else {
        next.add(status);
      }
      return next;
    });
  }, []);

  const clearFilters = useCallback(() => {
    setQuery("");
    setStatuses(new Set());
  }, []);

  const filters: BoardFilters = { query, statuses };

  return { filters, setQuery, toggleStatus, clearFilters };
}

