import { useState, useCallback, useMemo } from "react";
import type { Feature, BoardFilters } from "../model/board.types";

export function useFeatureRows(
  features: Feature[],
  filters: BoardFilters
) {
  const [expandedIds, setExpandedIds] = useState<Set<string>>(new Set());

  const toggle = useCallback((id: string) => {
    setExpandedIds((prev) => {
      const next = new Set(prev);
      if (next.has(id)) {
        next.delete(id);
      } else {
        next.add(id);
      }
      return next;
    });
  }, []);

  const filtered = useMemo(() => {
    const q = filters.query.toLowerCase().trim();
    const hasStatusFilter = filters.statuses.size > 0;

    return features
      .map((feature) => {
        const featureMatch = q && feature.name.toLowerCase().includes(q);
        const tasks = feature.tasks.filter((task) => {
          const statusOk =
            !hasStatusFilter || filters.statuses.has(task.status);
          if (!statusOk) return false;
          if (!q) return true;
          if (featureMatch) return true;
          return (
            task.title.toLowerCase().includes(q) ||
            task.id.toLowerCase().includes(q)
          );
        });
        return { ...feature, tasks };
      })
      .filter((f) => f.tasks.length > 0);
  }, [features, filters]);

  return { filtered, expandedIds, toggle };
}

