import {
  createContext,
  useContext,
  useState,
  useCallback,
  type ReactNode,
} from "react";
import { useBoardFilters } from "../../hooks/useBoardFilters";
import { useFeatureRows } from "../../hooks/useFeatureRows";
import { SAMPLE_FEATURES } from "../../model/sample-features";
import type { BoardState, TaskStatus } from "../../model/board.types";

const KanbanBoardContext = createContext<BoardState | null>(null);

interface KanbanBoardProviderProps {
  children: ReactNode;
  workspaceId: string;
}

export function KanbanBoardProvider({
  children,
  workspaceId,
}: KanbanBoardProviderProps) {
  const features = SAMPLE_FEATURES;
  const { filters, setQuery, toggleStatus, clearFilters } = useBoardFilters();
  const { filtered, expandedIds, toggle } = useFeatureRows(features, filters);

  const [selectedTaskId, setSelectedTaskId] = useState<string | null>(null);
  const [switcherOpen, setSwitcherOpen] = useState(false);
  const [addWorkspaceModalOpen, setAddWorkspaceModalOpen] = useState(false);

  const toggleStatus_: (status: TaskStatus) => void = useCallback(
    (s) => toggleStatus(s),
    [toggleStatus]
  );

  const value: BoardState = {
    workspaceId,
    features,
    filters,
    expandedFeatureIds: expandedIds,
    selectedTaskId,
    switcherOpen,
    addWorkspaceModalOpen,
    setQuery,
