import type { Feature } from "../../model/board.types";
import { useKanbanBoard } from "../KanbanBoard/KanbanBoard.context";

interface FeatureRowProps {
  feature: Feature;
}

export function FeatureRow({ feature }: FeatureRowProps) {
  const { expandedFeatureIds, toggleFeature } = useKanbanBoard();
  const isExpanded = expandedFeatureIds.has(feature.id);
  const done = feature.tasks.filter((t) => t.status === "done").length;

  return (
    <div>
      <button
        type="button"
        onClick={() => toggleFeature(feature.id)}
        aria-expanded={isExpanded}
      >
        {isExpanded ? "▼" : "►"} {feature.name} ({done}/{feature.tasks.length})
      </button>
      {isExpanded && (
        <div>
          {feature.tasks.map((task) => (
            <span key={task.id}>{task.title}</span>
          ))}
        </div>
      )}
    </div>
  );
}

