import { useState } from "react";
import type { Task } from "../../../tasks/model/task.types";
import type { TaskStatus } from "../../model/board.types";

const STATUS_COLORS: Record<TaskStatus, string> = {
  todo: "var(--status-todo)",
  ready: "var(--status-ready)",
  in_progress: "var(--status-in-progress)",
  blocked: "var(--status-blocked)",
  in_review: "var(--status-in-review)",
  done: "var(--status-done)",
  cancelled: "var(--status-cancelled)",
};

interface SegmentBarProps {
  tasks: Task[];
}

export function SegmentBar({ tasks }: SegmentBarProps) {
  const [hoveredIndex, setHoveredIndex] = useState<number | null>(null);

  return (
    <div style={{ display: "flex", width: "6rem", height: "0.75rem", gap: "1px" }}>
      {tasks.map((task, i) => (
        <div
          key={task.id}
          style={{
            flex: 1,
            backgroundColor: STATUS_COLORS[task.status as TaskStatus],
            opacity: hoveredIndex === i ? 1 : 0.75,
            transform: hoveredIndex === i ? "scaleY(1.2)" : "none",
            transition: "opacity 150ms, transform 150ms",
            cursor: "default",
            position: "relative",
          }}
          onMouseEnter={() => setHoveredIndex(i)}
          onMouseLeave={() => setHoveredIndex(null)}
          title={`${task.id}: ${task.status}`}
        />
      ))}
    </div>
  );
}

