import type { Task } from "../../model/task.types";
import type { TaskStatus } from "../../../board/model/board.types";

const NEXT_ACTION: Partial<Record<TaskStatus, string>> = {
  todo: "Approve stage",
  ready: "Claim by agent",
  in_progress: "Submit for review",
  blocked: "Resolve block",
  in_review: "Approve review",
};

interface TaskCardProps {
  task: Task;
  index: number;
  onClick?: () => void;
}

export function TaskCard({ task, index, onClick }: TaskCardProps) {
  const nextAction = NEXT_ACTION[task.status];
  const actorType = task.execution.actorType;

  return (
    <div
      onClick={onClick}
      style={{ cursor: "pointer" }}
      role="button"
      tabIndex={0}
      onKeyDown={(e) => e.key === "Enter" && onClick?.()}
    >
      <div>
        <span style={{ fontFamily: "monospace" }}>T{index + 1}</span>
        {task.title}
      </div>
      {nextAction && <div>{nextAction}</div>}
      {actorType && (
        <span
          title={actorType === "agent" ? "Agent" : "Human"}
          style={{
            backgroundColor:
              actorType === "agent"
                ? "rgba(139,92,246,0.1)"
                : "rgba(59,130,246,0.1)",
          }}
        >
          {actorType}
        </span>
      )}
    </div>
  );
}

