import {
  TaskDetailSheetProvider,
  useTaskDetailSheet,
} from "./TaskDetailSheet.context";
import { type ReactNode } from "react";
import type { Task } from "../../model/task.types";

interface RootProps {
  children: ReactNode;
}

function Root({ children }: RootProps) {
  return (
    <TaskDetailSheetProvider>{children}</TaskDetailSheetProvider>
  );
}

function Sheet() {
  const { selectedTask, isOpen, close } = useTaskDetailSheet();
  if (!isOpen || !selectedTask) return null;

  return (
    <div
      role="dialog"
      aria-modal="true"
      style={{ position: "fixed", right: 0, top: 0, bottom: 0 }}
    >
      <div>
        <button type="button" onClick={close} aria-label="Close">
          ×
        </button>
        <h2>
          <span>{selectedTask.id}</span> {selectedTask.title}
        </h2>
        <TaskMeta task={selectedTask} />
      </div>
    </div>
  );
}

function TaskMeta({ task }: { task: Task }) {
  return (
    <div>
      <div>Status: {task.status}</div>
      {task.branch && <div>Branch: {task.branch}</div>}
      {task.blockedReason && <div>Blocked: {task.blockedReason}</div>}
      {task.pr?.url && (
        <a href={task.pr.url} target="_blank" rel="noreferrer">
          PR: {task.pr.url}
        </a>
      )}
    </div>
  );
}

function TaskDetailSheetRoot({ children }: RootProps) {
  return <Root>{children}</Root>;
}

export const TaskDetailSheet =
  TaskDetailSheetRoot as typeof TaskDetailSheetRoot & {
    Sheet: typeof Sheet;
  };

TaskDetailSheet.Sheet = Sheet;

