import { createRoute, redirect, useNavigate } from "@tanstack/react-router";
import { Route as rootRoute } from "../__root";
import { authStorage } from "@/features/auth";
import { WorkspaceList, WorkspaceCard } from "@/features/workspaces";
import { WorkspaceImport } from "@/features/workspaces";
import { useWorkspaceList } from "@/features/workspaces";

export const Route = createRoute({
  getParentRoute: () => rootRoute,
  path: "/workspaces",
  beforeLoad: () => {
    if (!authStorage.isLoggedIn()) {
      throw redirect({ to: "/login" });
    }
  },
  component: WorkspacesPage,
});

function WorkspacesContent() {
  const { workspaces, removeWorkspace } = useWorkspaceList();
  const navigate = useNavigate();
  return (
    <div>
      {workspaces.map((ws) => (
        <WorkspaceCard
          key={ws.id}
          workspace={ws}
          onClick={() => void navigate({ to: "/workspaces/$workspaceId", params: { workspaceId: ws.id } })}
          onDelete={() => removeWorkspace(ws.id)}
        />
      ))}
    </div>
  );
}

function WorkspacesPage() {
  const navigate = useNavigate();
  return (
    <div>
      <header>
        <button
          type="button"
          onClick={() => {
            authStorage.logout();
            void navigate({ to: "/login" });
          }}
        >
          Sign out
        </button>
      </header>
      <main>
        <h1>Welcome back!</h1>
        <WorkspaceList.Root>
          <WorkspacesContent />
        </WorkspaceList.Root>
        <WorkspaceImport.Root
          onImported={(id) => void navigate({ to: "/workspaces/$workspaceId", params: { workspaceId: id } })}
        >
          <WorkspaceImport.UrlField />
          <WorkspaceImport.PrivateRepositorySwitch />
          <WorkspaceImport.TokenField />
          <WorkspaceImport.ErrorMessage />
          <WorkspaceImport.SubmitButton />
        </WorkspaceImport.Root>
        <button type="button" disabled>
          + Create a new workspace
        </button>
      </main>
    </div>
  );
}

