import {
  createContext,
  useContext,
  useState,
  useCallback,
  useMemo,
  type ReactNode,
} from "react";
import { useBoardFilters } from "../../hooks/useBoardFilters";
import { useFeatureRows } from "../../hooks/useFeatureRows";
import { SAMPLE_FEATURES } from "../../model/sample-features";
import type { BoardState, TaskStatus } from "../../model/board.types";

const KanbanBoardContext = createContext<BoardState | null>(null);

interface KanbanBoardProviderProps {
  children: ReactNode;
  workspaceId: string;
}

export function KanbanBoardProvider({
  children,
  workspaceId,
}: KanbanBoardProviderProps) {
  const features = SAMPLE_FEATURES;
  const { filters, setQuery, toggleStatus, clearFilters } = useBoardFilters();
  const { filtered, expandedIds, toggle } = useFeatureRows(features, filters);

  const [selectedTaskId, setSelectedTaskId] = useState<string | null>(null);
  const [switcherOpen, setSwitcherOpen] = useState(false);
  const [addWorkspaceModalOpen, setAddWorkspaceModalOpen] = useState(false);

  const handleToggleStatus = useCallback(
    (s: TaskStatus) => toggleStatus(s),
    [toggleStatus]
  );
  const handleSelectTask = useCallback(
    (id: string | null) => setSelectedTaskId(id),
    []
  );
  const handleSetSwitcherOpen = useCallback(
    (open: boolean) => setSwitcherOpen(open),
    []
  );
  const handleSetAddWorkspaceModalOpen = useCallback(
    (open: boolean) => setAddWorkspaceModalOpen(open),
    []
  );

  const value: BoardState = useMemo(
    () => ({
      workspaceId,
      features,
      filters,
      expandedFeatureIds: expandedIds,
      selectedTaskId,
      switcherOpen,
      addWorkspaceModalOpen,
      setQuery,
      toggleStatus: handleToggleStatus,
      clearFilters,
      toggleFeature: toggle,
      selectTask: handleSelectTask,
      setSwitcherOpen: handleSetSwitcherOpen,
      setAddWorkspaceModalOpen: handleSetAddWorkspaceModalOpen,
      filteredFeatures: filtered,
    }),
    [
      workspaceId,
      features,
      filters,
      expandedIds,
      selectedTaskId,
      switcherOpen,
      addWorkspaceModalOpen,
      setQuery,
      handleToggleStatus,
      clearFilters,
      toggle,
      handleSelectTask,
      handleSetSwitcherOpen,
      handleSetAddWorkspaceModalOpen,
      filtered,
    ]
  );

  return (
    <KanbanBoardContext.Provider value={value}>
      {children}
    </KanbanBoardContext.Provider>
  );
}

export function useKanbanBoard() {
  const ctx = useContext(KanbanBoardContext);
  if (!ctx)
    throw new Error("useKanbanBoard must be used within KanbanBoardProvider");
  return ctx;
}

