import { type ReactNode } from "react";
import {
  AddWorkspaceModalProvider,
  useAddWorkspaceModal,
} from "./AddWorkspaceModal.context";
import { WorkspaceImport } from "../WorkspaceImport/WorkspaceImport";

interface RootProps {
  children: ReactNode;
}

function Root({ children }: RootProps) {
  return <AddWorkspaceModalProvider>{children}</AddWorkspaceModalProvider>;
}

interface ModalProps {
  onImported?: (workspaceId: string) => void;
}

function Modal({ onImported }: ModalProps) {
  const { isOpen, close } = useAddWorkspaceModal();
  if (!isOpen) return null;

  return (
    <div role="dialog" aria-modal="true" onClick={close}>
      <div onClick={(e) => e.stopPropagation()}>
        <button type="button" onClick={close}>
          ×
        </button>
        <h2>Add workspace</h2>
        <WorkspaceImport
          onImported={(id) => {
            onImported?.(id);
            close();
          }}
        >
          <WorkspaceImport.UrlField />
          <WorkspaceImport.PrivateRepositorySwitch />
          <WorkspaceImport.TokenField />
          <WorkspaceImport.ErrorMessage />
          <WorkspaceImport.SubmitButton />
        </WorkspaceImport>
        <button type="button" disabled>
          Create workspace <span>Coming soon</span>
        </button>
      </div>
    </div>
  );
}

function AddWorkspaceModalRoot({ children }: RootProps) {
  return <Root>{children}</Root>;
}

export const AddWorkspaceModal =
  AddWorkspaceModalRoot as typeof AddWorkspaceModalRoot & {
    Modal: typeof Modal;
  };

AddWorkspaceModal.Modal = Modal;

