import { type ReactNode } from "react";
import {
  KanbanBoardProvider,
  useKanbanBoard,
} from "./KanbanBoard.context";

interface RootProps {
  children: ReactNode;
  workspaceId: string;
}

function Root({ children, workspaceId }: RootProps) {
  return (
    <KanbanBoardProvider workspaceId={workspaceId}>
      {children}
    </KanbanBoardProvider>
  );
}

function FeatureCount() {
  const { features } = useKanbanBoard();
  return <span>{features.length} features</span>;
}

function TaskCount() {
  const { features } = useKanbanBoard();
  const total = features.reduce((acc, f) => acc + f.tasks.length, 0);
  return <span>{total} tasks</span>;
}

function KanbanBoardRoot({ children, workspaceId }: RootProps) {
  return <Root workspaceId={workspaceId}>{children}</Root>;
}

export const KanbanBoard = KanbanBoardRoot as typeof KanbanBoardRoot & {
  FeatureCount: typeof FeatureCount;
  TaskCount: typeof TaskCount;
};

KanbanBoard.FeatureCount = FeatureCount;
KanbanBoard.TaskCount = TaskCount;
